content.text:
.stage{height:340px;position:relative;margin:7px 0 0;display:grid;place-items:center;isolation:isolate}
.stage:before{content:"";position:absolute;width:290px;height:290px;border-radius:50%;background:radial-gradient(circle,#9c61f429 0, #9c61f40a 48%,transparent 70%);z-index:-2}
.stand-art{width:210px;height:260px;position:relative;display:grid;place-items:center;transition:transform .35s,filter .35s;filter:drop-shadow(0 12px 30px #a357ff44)}
.stand-art .halo{position:absolute;width:145px;height:145px;border-radius:50%;background:radial-gradient(circle,#bd74ff42,transparent 69%);filter:blur(4px)}
.stand-art svg{position:relative;z-index:1;overflow:visible}
.stage.is-rolling .stand-art{animation:rollPulse .2s ease-in-out infinite alternate;filter:drop-shadow(0 0 28px #ff5e9d)}
.result{position:absolute;bottom:2px;left:0;right:0;text-align:center;min-height:47px}
.result-name{font-size:23px;font-weight:950;letter-spacing:-.03em}
.result-meta{font-size:10px;color:#b9b1c2;letter-spacing:.17em;text-transform:uppercase;font-weight:800;margin-top:4px}
.result-placeholder{color:#8f879a;font-size:12px;letter-spacing:.1em;text-transform:uppercase}
.modal-backdrop{position:fixed;inset:0;z-index:20;background:#090710bd;display:none;place-items:center;padding:20px}
.modal-backdrop.open{display:grid}
.modal{width:min(410px,100%);padding:22px;border-radius:20px;border:1px solid #ffffff1b;background:#1a1626;box-shadow:0 25px 100px #000b;text-align:center}
.modal .big-sigil{font-size:48px;color:var(--gold);margin:7px}
.modal h2{margin:6px 0;font-size:22px}
.modal p{color:#a49bac;font-size:12px;line-height:1.55}
.modal-actions{display:flex;gap:8px;margin-top:18px}
.modal-actions button{flex:1;padding:11px;border-radius:11px;border:1px solid var(--line);background:#ffffff09;font-size:10px;font-weight:900}
.modal-actions .primary{background:var(--gold);color:#211923;border-color:#ffe2a5}
.modal-close{position:absolute;right:calc(50% - 190px);top:calc(50% - 165px);background:none;border:0;color:#aaa;font-size:22px}

