32: <script>
33: const STANDS=[
34:  {name:'Hermit Purple',rarity:'Common',sigil:'❧',power:'A thorned path to hidden truth',echoes:3,portrait:'https://upload.wikimedia.org/wikipedia/en/d/dc/Jjbagroup.jpg'},
35:  {name:'Hierophant Green',rarity:'Common',sigil:'✣',power:'A jeweled guardian from afar',echoes:3,portrait:'https://upload.wikimedia.org/wikipedia/en/f/f6/Jojo13.jpg'},
36:  {name:'Silver Chariot',rarity:'Common',sigil:'⚔',power:'A flash of polished steel',echoes:3,portrait:'https://upload.wikimedia.org/wikipedia/en/d/dc/Jjbagroup.jpg'},
37:  {name:'Magicians Red',rarity:'Uncommon',sigil:'♨',power:'Commands the living flame',echoes:6,portrait:'https://upload.wikimedia.org/wikipedia/en/d/dc/Jjbagroup.jpg'},
38:  {name:'Crazy Diamond',rarity:'Uncommon',sigil:'◇',power:'Mends what fate has broken',echoes:6,portrait:'https://upload.wikimedia.org/wikipedia/en/d/dc/Jjbagroup.jpg'},
39:  {name:'Killer Queen',rarity:'Uncommon',sigil:'♛',power:'Turns quiet things explosive',echoes:6,portrait:'https://upload.wikimedia.org/wikipedia/en/b/b6/Jojo36.jpg'},
40:  {name:'Star Platinum',rarity:'Rare',sigil:'✦',power:'A guardian with impossible speed',echoes:12,portrait:'https://upload.wikimedia.org/wikipedia/en/9/9a/JotaroKujo.png'},
41:  {name:'The World',rarity:'Rare',sigil:'◉',power:'Commands a moment to stand still',echoes:12,portrait:'https://upload.wikimedia.org/wikipedia/en/d/d2/Dio_Brando.jpg'},
42:  {name:'Gold Experience',rarity:'Rare',sigil:'☀',power:'Gives life to the inanimate',echoes:12,portrait:'https://upload.wikimedia.org/wikipedia/en/b/b4/Giorno_Giovanna.png'},
43:  {name:'Sticky Fingers',rarity:'Epic',sigil:'⚡',power:'Opens a way through any wall',echoes:25,portrait:'https://upload.wikimedia.org/wikipedia/en/e/e3/Jojo49.jpg'},
44:  {name:'Stone Free',rarity:'Epic',sigil:'⛓',power:'Unravels into an unbreakable thread',echoes:25,portrait:'https://upload.wikimedia.org/wikipedia/en/8/84/Jolyne_Cujoh.png'},
45:  {name:'STAR PLATINUM: THE WORLD',rarity:'Legendary',sigil:'✹',power:'An instant stretched into eternity',echoes:60,portrait:'https://upload.wikimedia.org/wikipedia/en/9/9a/JotaroKujo.png'}
46: ];
47: const RARITIES=['Common','Uncommon','Rare','Epic','Legendary'];
48: const COLORS={Common:'#aaa3b5',Uncommon:'#75e2ad',Rare:'#70caff',Epic:'#c18bff',Legendary:'#ffcf70'};
49: const initial={spins:0,echoes:0,level:0,owned:{},equipped:null,best:0,pity:0};
50: let state={...initial};
51: try{const saved=JSON.parse(localStorage.getItem('standbound-save'));if(saved&&typeof saved==='object')state={...initial,...saved,owned:saved.owned||{}}}catch{}
52: let busy=false,auto=false,filter='all',autoTimer=null,toastTimer=null,lastStand=null;
53: const $=id=>document.getElementById(id);
54: function save(){try{localStorage.setItem('standbound-save',JSON.stringify(state))}catch{}}
55: function rarityIndex(r){return RARITIES.indexOf(r)}
56: function getStand(name){return STANDS.find(s=>s.name===name)}
57: function notify(html){const t=$('toast');t.innerHTML=html;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
58: function render(){
59:  $('echoes').textContent=state.echoes.toLocaleString();$('spinCount').textContent=state.spins.toLocaleString();
60:  const count=Object.keys(state.owned).filter(n=>state.owned[n]>0).length;$('discoverCount').textContent=`${count}/${STANDS.length}`;$('archiveCount').textContent=`${count}/${STANDS.length}`;
61:  $('bestRarity').textContent=state.best?RARITIES[state.best]:'—';$('equippedName').textContent=state.equipped||'None';$('equippedName').title=state.equipped||'None';
62:  $('pityLabel').textContent=`${state.pity} / 10`;$('pityBar').style.width=`${Math.min(100,state.pity*10)}%`;
63:  const luck=1+state.level*.15;$('luckTag').textContent=`LUCK ×${luck.toFixed(2)}`;
64:  const cost=25+state.level*35;$('upgradeInfo').textContent=`+15% rare luck · Level ${state.level}`;$('upgradeBtn').innerHTML=`✧ ${cost}`;$('upgradeBtn').disabled=state.echoes<cost;
65:  renderCollection();
66: }
67: function renderCollection(){const grid=$('collectionGrid');grid.innerHTML='';const list=STANDS.filter(s=>(filter==='all'||s.rarity===filter)&&(state.owned[s.name]||0)>0);for(const s of list){const el=document.createElement('button');el.className=`stand-card${state.equipped===s.name?' equipped':''}`;el.style.setProperty('--rarity',COLORS[s.rarity]);el.setAttribute('aria-label',`${s.name}, ${s.rarity}. Tap to equip.`);el.innerHTML=`<div class="stand-card-top"><span class="rarity-dot"></span><span class="rarity-label">${s.rarity}</span></div><div class="card-sigil">${s.sigil}</div><h3>${s.name}</h3><p>${state.equipped===s.name?'✦ EQUIPPED':s.power}</p>${state.owned[s.name]>1?`<span class="card-count">×${state.owned[s.name]}</span>`:''}`;el.addEventListener('click',()=>equip(s));grid.append(el)}const remaining=Math.max(0,8-list.length);for(let i=0;i<remaining;i++){const blank=document.createElement('div');blank.className='empty-card';blank.textContent='Fate unknown';grid.append(blank)}}
68: function equip(s){state.equipped=s.name;save();render();notify(`Equipped <b>${s.name}</b> · ${s.rarity}`)}
69: function rarityRoll(){if(state.pity>=9)return 'Epic';const luck=1+state.level*.15;const weights=[54,26,13,5.5,1.5].map((w,i)=>w*Math.pow(luck,i));let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<weights.length;i++){n-=weights[i];if(n<=0)return RARITIES[i]}return 'Common'}
70: function tone(freq=440,duration=.11){if(!soundOn)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);o.onended=()=>ctx.close()}catch{}}
71: function summon(){if(busy)return;busy=true;$('rollBtn').disabled=true;$('stage').classList.add('is-rolling');$('resultName').innerHTML='<span class="result-placeholder">Fate is turning…</span>';$('resultMeta').textContent='THE THREADS ARE ALIGNING';tone(320,.15);setTimeout(()=>{
72:  const rarity=rarityRoll(),choices=STANDS.filter(s=>s.rarity===rarity),stand=choices[Math.floor(Math.random()*choices.length)],wasOwned=(state.owned[stand.name]||0)>0;
73:  state.spins++;state.pity=rarityIndex(rarity)>=3?0:state.pity+1;state.best=Math.max(state.best,rarityIndex(rarity));state.owned[stand.name]=(state.owned[stand.name]||0)+1;
74:  if(wasOwned){state.echoes+=stand.echoes;tone(560,.2)}else{lastStand=stand;tone(rarity==='Legendary'?880:660,.3)}
75:  $('stage').classList.remove('is-rolling');$('resultName').textContent=stand.name;$('resultName').style.color=COLORS[rarity];$('resultMeta').textContent=`${rarity.toUpperCase()} · ${stand.power.toUpperCase()}`;
76:  $('standArt').style.filter=`drop-shadow(0 10px 28px ${COLORS[rarity]}88) hue-rotate(${rarityIndex(rarity)*34}deg)`;
77:  $('standArt').style.transform=`scale(${1+rarityIndex(rarity)*.035})`;
78:  save();render();busy=false;$('rollBtn').disabled=false;
79:  if(wasOwned)notify(`Duplicate <b>${stand.name}</b> · +${stand.echoes} echoes`);else showDiscovery(stand);
80:  },850)}
81: function showDiscovery(s){$('modalSigil').textContent=s.sigil;$('modalSigil').style.color=COLORS[s.rarity];$('modalRarity').textContent=s.rarity.toUpperCase()+' STAND DISCOVERED';$('modalRarity').style.color=COLORS[s.rarity];$('modalTitle').textContent=s.name;$('modalText').textContent=`${s.power}. A new fate joins your archive. You can equip this Stand or convert it to ${s.echoes} echoes.`;$('modalBackdrop').classList.add('open')}
82: function closeModal(){ $('modalBackdrop').classList.remove('open') }
83: let soundOn=false;
84: $('rollBtn').addEventListener('click',summon);
85: $('autoBtn').addEventListener('click',()=>{auto=!auto;$('autoBtn').classList.toggle('active',auto);$('autoBtn').innerHTML=auto?'◉ &nbsp;STOP':'◉ &nbsp;AUTO';if(auto){autoTimer=setInterval(()=>{if(!busy&&!$('modalBackdrop').classList.contains('open'))summon()},1250);notify('Auto-spin <b>started</b>')}else{clearInterval(autoTimer);notify('Auto-spin <b>paused</b>')}});
86: $('upgradeBtn').addEventListener('click',()=>{const cost=25+state.level*35;if(state.echoes<cost)return;state.echoes-=cost;state.level++;save();render();notify(`Fortune's Favor upgraded · <b>Luck ×${(1+state.level*.15).toFixed(2)}</b>`);tone(730,.24)});
87: $('filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderCollection()});
88: $('modalEquip').addEventListener('click',()=>{if(lastStand)state.equipped=lastStand.name;save();render();closeModal();notify(`<b>${lastStand.name}</b> equipped!`)});
89: $('modalSell').addEventListener('click',()=>{if(!lastStand)return;state.owned[lastStand.name]=Math.max(0,(state.owned[lastStand.name]||1)-1);if(!state.owned[lastStand.name])delete state.owned[lastStand.name];state.echoes+=lastStand.echoes;save();render();closeModal();notify(`Converted <b>${lastStand.name}</b> · +${lastStand.echoes} echoes`)});
90: $('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
91: $('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').style.color=soundOn?'var(--gold)':'#c5bdce';$('soundBtn').title=soundOn?'Mute sound':'Enable sound';if(soundOn)tone(640,.16)});
92: render();
93: </script>
94: </body>
95: </html>

