import urllib.request,re,time
pages=['Joseph_Joestar','Noriaki_Kakyoin','Jean_Pierre_Polnareff','Muhammad_Avdol','Josuke_Higashikata','Yoshikage_Kira','Bruno_Bucciarati','Jotaro_Kujo','Dio_Brando','Giorno_Giovanna','Jolyne_Cujoh']
